import React, { useState } from 'react';
import './AgentList.css';

function AgentRegistrationForm({ onClose, onRegister }) {
  const [form, setForm] = useState({
    name: '',
    company: '',
    role: '',
    email: '',
    mobile: '',
    verified: false,
    status: 'Active'
  });

  function handleChange(e) {
    const { name, value, type, checked } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  }

  function handleSubmit(e) {
    e.preventDefault();
    onRegister(form);
    onClose();
  }

  return (
    <div className="agent-form-modal-backdrop">
      <div className="agent-form-modal">
        <h3>Add New Agent</h3>
        <form onSubmit={handleSubmit} className="agent-form">
          <label>
            Name:
            <input name="name" value={form.name} onChange={handleChange} required />
          </label>
          <label>
            Company:
            <input name="company" value={form.company} onChange={handleChange} required />
          </label>
          <label>
            Role:
            <input name="role" value={form.role} onChange={handleChange} required />
          </label>
          <label>
            Email:
            <input name="email" value={form.email} onChange={handleChange} required type="email" />
          </label>
          <label>
            Mobile:
            <input name="mobile" value={form.mobile} onChange={handleChange} required />
          </label>
          <label>
            Verified:&nbsp;
            <input name="verified" type="checkbox" checked={form.verified} onChange={handleChange} />
          </label>
          <label>
            Status:
            <select name="status" value={form.status} onChange={handleChange}>
              <option value="Active">Active</option>
              <option value="Locked">Locked</option>
            </select>
          </label>
          <div className="agent-form-actions">
            <button type="submit" className="add-agent-btn">Add Agent</button>
            <button type="button" className="agent-form-cancel" onClick={onClose}>Cancel</button>
          </div>
        </form>
      </div>
    </div>
  );
}

const initialAgents = [
  {
    name: "Adam Trantow",
    company: "Mohr, Langworth and Hills",
    role: "Sales Agent",
    email: "Adam.Trantow@test.com",
    mobile: "(942) 208-5834 x1417",
    verified: true,
    status: "Active"
  },
  {
    name: "Billy Stoltenberg",
    company: "Medhurst, Moore and Franey",
    role: "Sales Leader",
    email: "Billy.Stoltenberg@test.com",
    mobile: "(499) 633-7585",
    verified: true,
    status: "Locked"
  },
  {
    name: "Betty Hammes",
    company: "Waelchi - VonRueden",
    role: "Sales Agent",
    email: "Betty.Hammes@test.com",
    mobile: "(427) 981-0673",
    verified: true,
    status: "Active"
  }
];

export default function AgentList() {
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [agents, setAgents] = useState(initialAgents);

  const filteredAgents = agents.filter(agent =>
    agent.name.toLowerCase().includes(search.toLowerCase())
  );

  function handleAddAgent(agent) {
    setAgents([...agents, agent]);
  }

  return (
    <div className="agentlist-container">
      <div className="agentlist-header">
        <h2>Agents</h2>
        <button className="add-agent-btn" onClick={() => setShowForm(true)}>
          + NEW AGENT
        </button>
      </div>
      <div className="agentlist-search">
        <input
          type="text"
          placeholder="Search user..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
      </div>
      <div className="agentlist-table-wrap">
        <table className="agentlist-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Company</th>
              <th>Role</th>
              <th>Email</th>
              <th>Mobile</th>
              <th>Verified</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {filteredAgents.map((agent, i) => (
              <tr key={i}>
                <td>{agent.name}</td>
                <td>{agent.company}</td>
                <td>{agent.role}</td>
                <td>{agent.email}</td>
                <td>{agent.mobile}</td>
                <td>
                  {agent.verified ? (
                    <span className="verified-check" title="Verified">&#10003;</span>
                  ) : (
                    <span className="not-verified" title="Not Verified">&#10007;</span>
                  )}
                </td>
                <td>
                  <span className={`status-badge ${agent.status === "Active" ? "active" : "locked"}`}>
                    {agent.status}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal for New Agent */}
      {showForm && (
        <AgentRegistrationForm
          onClose={() => setShowForm(false)}
          onRegister={handleAddAgent}
        />
      )}
    </div>
  );
}
